-- Sign-in and owners of the data.
--
-- Generated by `drizzle-kit generate` and completed by hand: the contacts and
-- groups that are already in the database go to the owner, the user with the
-- email of OWNER_EMAIL. scripts/migrate.mts puts that email, in one spelling,
-- into the setting crm.owner_email of its connection before the migrations.
--
-- Nothing is deleted. Drizzle applies all pending migrations in one
-- transaction: if any step fails, the database stays as it was.

-- 1. Tables of Better Auth and of the limit of sign-in emails.
CREATE TABLE "account" (
	"id" text PRIMARY KEY NOT NULL,
	"account_id" text NOT NULL,
	"provider_id" text NOT NULL,
	"user_id" text NOT NULL,
	"access_token" text,
	"refresh_token" text,
	"id_token" text,
	"access_token_expires_at" timestamp with time zone,
	"refresh_token_expires_at" timestamp with time zone,
	"scope" text,
	"password" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "login_link_sends" (
	"id" integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "login_link_sends_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"email" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "session" (
	"id" text PRIMARY KEY NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"token" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"ip_address" text,
	"user_agent" text,
	"user_id" text NOT NULL,
	CONSTRAINT "session_token_unique" UNIQUE("token")
);
--> statement-breakpoint
CREATE TABLE "user" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"email_verified" boolean DEFAULT false NOT NULL,
	"image" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "user_email_unique" UNIQUE("email")
);
--> statement-breakpoint
CREATE TABLE "verification" (
	"id" text PRIMARY KEY NOT NULL,
	"identifier" text NOT NULL,
	"value" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "account" ADD CONSTRAINT "account_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "session" ADD CONSTRAINT "session_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "account_user_id_idx" ON "account" USING btree ("user_id");--> statement-breakpoint
CREATE INDEX "login_link_sends_email_created_at_idx" ON "login_link_sends" USING btree ("email","created_at");--> statement-breakpoint
CREATE INDEX "session_user_id_idx" ON "session" USING btree ("user_id");--> statement-breakpoint
CREATE INDEX "verification_identifier_idx" ON "verification" USING btree ("identifier");--> statement-breakpoint

-- 2. The owner column, empty for now.
ALTER TABLE "contacts" ADD COLUMN "owner_id" text;--> statement-breakpoint
ALTER TABLE "groups" ADD COLUMN "owner_id" text;--> statement-breakpoint

-- 3. The rows that are already here go to the owner. The owner is created if
-- nobody has signed in with that email yet: on the first sign-in Better Auth
-- finds this user by the email. Without the email the migration stops here
-- with a clear error, before anything is changed.
DO $$
DECLARE
	owner_email text := nullif(current_setting('crm.owner_email', true), '');
	owner_user_id text;
BEGIN
	IF NOT EXISTS (SELECT 1 FROM "contacts") AND NOT EXISTS (SELECT 1 FROM "groups") THEN
		RETURN;
	END IF;

	IF owner_email IS NULL THEN
		RAISE EXCEPTION 'OWNER_EMAIL is not set: the database has contacts or groups, and they need an owner. Add OWNER_EMAIL to .env and run the migrations again.';
	END IF;

	INSERT INTO "user" ("id", "name", "email", "email_verified")
	VALUES (gen_random_uuid()::text, '', owner_email, true)
	ON CONFLICT ("email") DO NOTHING;

	SELECT "id" INTO owner_user_id FROM "user" WHERE "email" = owner_email;

	UPDATE "contacts" SET "owner_id" = owner_user_id WHERE "owner_id" IS NULL;
	UPDATE "groups" SET "owner_id" = owner_user_id WHERE "owner_id" IS NULL;
END
$$;--> statement-breakpoint

-- 4. From now on every contact and every group has an owner.
ALTER TABLE "contacts" ALTER COLUMN "owner_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "groups" ALTER COLUMN "owner_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "contacts" ADD CONSTRAINT "contacts_owner_id_user_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "groups" ADD CONSTRAINT "groups_owner_id_user_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "contacts_owner_id_idx" ON "contacts" USING btree ("owner_id");--> statement-breakpoint

-- 5. A group name is unique for one owner only: two users may each have "Друзья".
DROP INDEX "groups_name_unique_idx";--> statement-breakpoint
CREATE UNIQUE INDEX "groups_owner_id_name_unique_idx" ON "groups" USING btree ("owner_id",replace(lower("name"), 'ё', 'е'));
